import Foundation

/// Unicode CLDR / GitHub-style emoji shortcodes (`:speaker_high_volume:`),
/// as YouTube live chat delivers them through Piped. Generated from the
/// `emoji` Python package's CLDR names + aliases; 4946 entries.
enum EmojiShortcodes {
    /// Replaces `:name:` tokens with their emoji; unknown names are left as-is.
    static func emojized(_ text: String) -> String {
        guard text.contains(":") else { return text }
        var output = ""
        output.reserveCapacity(text.count)
        var index = text.startIndex
        while index < text.endIndex {
            guard text[index] == ":",
                let close = text[text.index(after: index)...].firstIndex(of: ":"),
                close > text.index(after: index)
            else {
                output.append(text[index])
                index = text.index(after: index)
                continue
            }
            let name = text[text.index(after: index)..<close]
            if name.count <= 64, let emoji = table[name.lowercased()] {
                output.append(emoji)
                index = text.index(after: close)
            } else {
                output.append(text[index])
                index = text.index(after: index)
            }
        }
        return output
    }

    static let table: [String: String] = {
        var map: [String: String] = [:]
        map.reserveCapacity(4946)
        for line in source.split(separator: "\n") {
            guard let tab = line.firstIndex(of: "\t") else { continue }
            map[String(line[..<tab])] = String(line[line.index(after: tab)...])
        }
        return map
    }()

